create or replace function api.insert_hold(
    p_id uuid,
    p_item_id uuid,
    p_patron_id uuid,
    p_note text,
    p_actor_id uuid,
    p_actor_roles text[]
) returns setof public.holds
language plpgsql
security definer
set search_path = public
as $$
declare
    v_row public.holds;
begin
    -- この txn が触る行(ガードが読む親・実行者の行・これから書く行)を、表名のバイト順で全部掴んでから書く(交錯しても判定の前提が動かず、掴む順が 1 つなので詰まらない)。
    perform 1
    from public.holds t
    where t.id = p_id
    for update of t;

    perform 1
    from public.patrons la
    where la.id = p_actor_id
    for share of la;

    -- 同じ id の行が既にあれば、挿入の前に再送の枝へ進む(行の before insert トリガは一意の衝突の判定より先に走るので、挿入まで進むと押し直しでも番号のずらし・上端の断り・確かめのトリガが動く)。上の掴みの後に見るので、同じ鍵の 1 回目がまだコミットしていなければここで待ってから見る。既にある行は上の掴みが掴んでいる(消す txn がまだコミットしていなければそこで待ち、消えていれば挿入へ進んで作り直しの断りに合流する)。
    if exists (select 1 from public.holds where id = p_id) then
        if not (((coalesce('patron' = any(p_actor_roles), false) and exists (select 1 from public.patrons a where a.id = p_actor_id)) and coalesce((p_patron_id) = p_actor_id, false))) then
            raise exception using errcode = 'UC403', message = 'usecase_forbidden:hold.create';
        end if;
        -- 再送として返すのは、実行者が作った行(patron_id = 実行者)だけ。他人の行は中身を返さず競合にする(実行者が null の呼び出しは誰の行とも一致しない)。
        select t.* into v_row from public.holds t
         where t.id = p_id and p_actor_id is not null and t.patron_id = p_actor_id;
        if found then
            -- 同じ鍵で入力が違う再送は返さない(1 回目は書けている。2 回目の入力を書けたと偽らず、行も増やさない)。
            if v_row.item_id is distinct from (p_item_id)
            or v_row.note is distinct from (p_note) then
                raise exception using errcode = 'UC412', message = 'usecase_guard:' || 'hold.create', detail = 'resend_input_mismatch';
            end if;
            perform set_config('st.resent_id', p_id::text, true);
            return next v_row;
            return;
        end if;
        raise exception using errcode = 'UC409', message = 'usecase_conflict:hold.create';
    end if;

    insert into public.holds (
        id, item_id, patron_id, note
    )
    select
        p_id,
        p_item_id,
        p_patron_id,
        p_note
    where ((coalesce('patron' = any(p_actor_roles), false) and exists (select 1 from public.patrons a where a.id = p_actor_id)) and coalesce((p_patron_id) = p_actor_id, false))
    on conflict (id) do nothing
    returning * into v_row;

    -- 0 行の理由を分類する(ロール → 再送 → 状態 → ガード。作成に自分の状態の段は無い)。
    if not found then
        if not (((coalesce('patron' = any(p_actor_roles), false) and exists (select 1 from public.patrons a where a.id = p_actor_id)) and coalesce((p_patron_id) = p_actor_id, false))) then
            raise exception using errcode = 'UC403', message = 'usecase_forbidden:hold.create';
        end if;
        -- 0 行 = 同じ id で作成済み(冪等な再送)か、前提が崩れた(競合)。id の実在で見分ける。
        if exists (select 1 from public.holds where id = p_id) then
            -- 再送として返すのは、実行者が作った行(patron_id = 実行者)だけ。他人の行は中身を返さず競合にする(実行者が null の呼び出しは誰の行とも一致しない)。
            select t.* into v_row from public.holds t
             where t.id = p_id and p_actor_id is not null and t.patron_id = p_actor_id;
            if found then
                -- 同じ鍵で入力が違う再送は返さない(1 回目は書けている。2 回目の入力を書けたと偽らず、行も増やさない)。
                if v_row.item_id is distinct from (p_item_id)
                or v_row.note is distinct from (p_note) then
                    raise exception using errcode = 'UC412', message = 'usecase_guard:' || 'hold.create', detail = 'resend_input_mismatch';
                end if;
                perform set_config('st.resent_id', p_id::text, true);
                return next v_row;
                return;
            end if;
            raise exception using errcode = 'UC409', message = 'usecase_conflict:hold.create';
        end if;
        -- 照会は 3 つとも通った = 照会と書き込みの間に行が動いた(競合)。
        raise exception using errcode = 'UC409', message = 'usecase_conflict:hold.create';
    end if;
    -- 同じ鍵の作成が監査ログに既にある = 1 回目の行が消された後の押し直し。作り直さずに断る(点検 23 回目 O23-2)。
    if exists (select 1 from public.domain_events r where r.entity_id = p_id and r.event_id = 'hold.create') then
        if exists (select 1 from public.domain_events r where r.entity_id = p_id and r.event_id = 'hold.create' and r.actor_id is not distinct from p_actor_id) then
            raise exception using errcode = 'UC412', message = 'usecase_guard:' || 'hold.create', detail = 'resend_target_deleted';
        end if;
        raise exception using errcode = 'UC409', message = 'usecase_conflict:hold.create';
    end if;

    insert into public.domain_events (event_id, entity, entity_id, actor_id, payload)
    values (
        'hold.create', 'hold', v_row.id, p_actor_id,
        jsonb_build_object(
            'item_id', p_item_id
        )
            || jsonb_build_object('redacted', array['note']::text[])
    );

    return next v_row;
end;
$$;

